@15 n="valence_electron_density" d="Occupied H3-convention valence-electron count per cubic angstrom, with missing valences excluded from the composition mean." B=962
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    atoms = 0.0
    known = 0.0
    electrons = 0.0
    for t in sites:
        o = max(0.0, t.get('occupancy', 1.0) or 0.0)
        atoms += o
        v = (props.get(t.get('element')) or {}).get('valence_electrons')
        if v is not None and v >= 0:
            known += o
            electrons += o * v
    if atoms <= 0 or known <= 0:
        return 0.0
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is not None and volume > 0:
        return electrons * atoms / (known * volume)
    volume_per_atom = s.get('volume_per_atom_A3')
    if volume_per_atom is None or volume_per_atom <= 0:
        volume_per_atom = (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3')
    if volume_per_atom is None or volume_per_atom <= 0:
        return 0.0
    return electrons / (known * volume_per_atom)
@end
@16 n="contact_radius_size_mismatch" d="Smooth-contact-weighted mean squared fractional covalent-radius difference; measures the size contrast of actual bonded neighbors." B=959
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    result = 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[i] > 0 and occ[j] > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0:
                x = d / (a + b)
                w = occ[i] * occ[j] / (1.0 + x ** 6)
                contrast = (a - b) / (a + b)
                result += w * contrast * contrast
                total += w
    if total <= 0:
        return 0.0
    return result / total
@end
